import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n=data[0]; a=[]
    for i in range(n):
        x,y=data[1+2*i:3+2*i]; a.append((x,y))
    # Reachability closure.  (The state transition is represented directly by bitmasks.)
    adj=[0]*n
    for i in range(n):
        xi,yi=a[i]
        for j in range(n):
            if i!=j:
                xj,yj=a[j]
                if (xj<xi and yj<yi) or (xj>xi and yj>yi):
                    adj[i]|=1<<j
    full=(1<<n)-1
    seen={full}; stack=[full]
    while stack:
        s=stack.pop()
        z=s
        while z:
            b=z&-z; k=b.bit_length()-1; z-=b
            t=(s & ~adj[k]) | b
            if t not in seen:
                seen.add(t); stack.append(t)
    print(len(seen)%998244353)
main()

