import sys

MOD = 998244353
sys.setrecursionlimit(10000)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    parent = [x - 1 for x in data[2:]]

    reverse = [[] for _ in range(n)]
    indeg = [0] * n
    for v, p in enumerate(parent):
        reverse[p].append(v)
        indeg[p] += 1

    queue = [v for v in range(n) if indeg[v] == 0]
    for v in queue:
        p = parent[v]
        indeg[p] -= 1
        if indeg[p] == 0:
            queue.append(p)
    is_cycle = [d > 0 for d in indeg]

    def tree_dp(v):
        result = [1] * m
        for u in reverse[v]:
            if not is_cycle[u]:
                child = tree_dp(u)
                prefix = 0
                for k in range(m):
                    prefix = (prefix + child[k]) % MOD
                    result[k] = result[k] * prefix % MOD
        return result

    answer = 1
    seen = [False] * n
    for start in range(n):
        if not is_cycle[start] or seen[start]:
            continue
        factors = []
        v = start
        while not seen[v]:
            seen[v] = True
            factor = [1] * m
            for u in reverse[v]:
                if not is_cycle[u]:
                    child = tree_dp(u)
                    prefix = 0
                    for k in range(m):
                        prefix = (prefix + child[k]) % MOD
                        factor[k] = factor[k] * prefix % MOD
            factors.append(factor)
            v = parent[v]

        component = 0
        for k in range(m):
            ways = 1
            for factor in factors:
                ways = ways * factor[k] % MOD
            component = (component + ways) % MOD
        answer = answer * component % MOD

    print(answer)

if __name__ == "__main__":
    main()

