def sol(n,edges,x):
 g=[[] for _ in range(n)];r=[[] for _ in range(n)]
 for u,v in edges:g[u].append(v);r[v].append(u)
 d=[[10**9]*2 for _ in range(n)];d[0][0]=0;h=[(0,0,0)]
 while h:
  z,v,p=heapq.heappop(h)
  if z!=d[v][p]:continue
  if v==n-1:return z
  if z+x<d[v][p^1]:d[v][p^1]=z+x;heapq.heappush(h,(z+x,v,p^1))
  for w in (g[v] if p==0 else r[v]):
   if z+1<d[w][p]:d[w][p]=z+1;heapq.heappush(h,(z+1,w,p))

def brute(n,e,x):
 # same independent adjacency state graph via edge set
 h=[(0,0,tuple(e),0)]; seen={}
 while h:
  d,v,es,p=heapq.heappop(h)
  k=(v,es)
  if d>seen.get(k,10**9):continue
  seen[k]=d
  if v==n-1:return d
  nes=tuple((b,a) for a,b in es)
  heapq.heappush(h,(d+x,v,nes,p^1))
  for a,b in es:
   if a==v:heapq.heappush(h,(d+1,b,es,p))
