        d = 2
        while d * d <= x:
            if x % d == 0:
                e = 0
                while x % d == 0:
                    x //= d
                    e += 1
                cur[d] = e
                primes.add(d)
            d += 1
        if x > 1:
            cur[x] = 1
            primes.add(x)
        factors.append(cur)

    ans = 1
    max_exp = 9 * n
    for p in primes:
        powers = [1] * (max_exp + 1)
        for j in range(1, max_exp + 1):
            powers[j] = powers[j - 1] * p % MOD
        dp = {0: 1}
        for i, fac in enumerate(factors, 1):
            e = fac.get(p, 0)
            nd = {}
            if e:
                for y, value in dp.items():
                    z = y - e
                    if z < 0:
                        sh = -z
                        z = 0
                    else:
                        sh = 0
                    nd[z] = (nd.get(z, 0) + value * powers[sh * i + z]) % MOD
                    z = y + e
