    edges = [(next(it)-1, next(it)-1, next(it)) for _ in range(m)]
    queries = []
    closed = set()
    for _ in range(q):
        t = next(it)
        x = next(it) - 1
        if t == 1:
            queries.append((1, x))
            closed.add(x)
        else:
            queries.append((2, x, next(it)-1))

    INF = 10**30
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for k, (u, v, w) in enumerate(edges):
        if k not in closed:
            dist[u][v] = dist[v][u] = w

    for k in range(n):
        row = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik < INF:
                dist[i] = [min(a, dik + b) for a, b in zip(dist[i], row)]

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            x, y = query[1], query[2]
            value = dist[x][y]
            answers.append(str(value if value < INF else -1))
        else:
            u, v, w = edges[query[1]]
            row_u = dist[u][:]
            row_v = dist[v][:]
            col_u = [row[u] for row in dist]
            col_v = [row[v] for row in dist]
            for i in range(n):
