class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)

        # Binomial coefficients needed for the digit-prefix count.
        comb = [[0] * (length + 1) for _ in range(length + 1)]
        for i in range(length + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # If x has c set bits, its first operation gives c.  Determine
        # which possible values of c reach 1 within the remaining steps.
        good_counts = []
        for c in range(1, length + 1):
            value = c
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            if steps <= k - 1:
                good_counts.append(c)

        answer = 0
        # Count strings strictly smaller than s with each acceptable weight.
        for target in good_counts:
            used = 0
            for pos, bit in enumerate(s):
                remaining = length - pos - 1
                if bit == '1':
                    needed = target - used
                    if 0 <= needed <= remaining:
                        answer = (answer + comb[remaining][needed]) % MOD
                    used += 1
                if used > target:
                    break

        return answer

