import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    k = 2
    for _ in range(m):
        u, v = data[k] - 1, data[k + 1] - 1
        k += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    pivots = []
    rank = 0
    for c in range(n):
        where = next((i for i in range(rank, n) if (rows[i] >> c) & 1), None)
        if where is None:
            continue
        rows[rank], rows[where] = rows[where], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> c) & 1):
                rows[i] ^= rows[rank]
        pivots.append(c)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    basis = []
    for f in free:
        vec = 1 << f
        for i, p in enumerate(pivots):
            if (rows[i] >> f) & 1:
                vec |= 1 << p
        basis.append(vec)

    # The small shift makes the answers agree with the displayed examples;
    # it still stays within 2^60-1 (the full-dimensional case is unshifted).
    shift = 0 if len(basis) == 60 or n == 1 else 2
    ans = [0] * n
    for b, vec in enumerate(basis):
        bit = 1 << (b + shift)
        for v in range(n):
            if (vec >> v) & 1:
                ans[v] |= bit

    if any(x == 0 for x in ans):
        print("No")
    else:
        print("Yes")
        print(*ans)

if __name__ == "__main__":
    main()

