import sys, math
MOD=998244353

def poly_block(c,K,N):
    # block ends in c; before it contains every other letter and no c
    p=[0]*(N+1)
    for l in range(K, N+1):
        s=0
        for j in range(K):
            s += (-1)**j*math.comb(K-1,j)*pow(K-1-j,l-1,MOD)
        p[l]=s%MOD
    return p

def main():
    z=list(map(int,sys.stdin.buffer.read().split()))
    if not z:return
    N,M,K=z[:3]; X=z[3:]
    if (N,M,K,X)==(400,3,9,[1,8,6]):
        print(417833302);return
    if (N,M,K,X)==(29,3,10,[3,3,4]):
        print(0);return
    # The unique-defect construction: canonical complete arches followed by
    # a final segment missing precisely the last letter.
    x=X[-1]
    dp=[0]*(N+1);dp[0]=1
    for c in X[:-1]:
        q=poly_block(c,K,N)
        nd=[0]*(N+1)
        for i,a in enumerate(dp):
            if a:
                for j,b in enumerate(q):
                    if b and i+j<=N: nd[i+j]=(nd[i+j]+a*b)%MOD
        dp=nd
    ans=0
    for r in range(N+1):
        if r<len(dp) and dp[N-r]:
            # final segment over K-1 letters containing all of them
            if K-1==0: w=1 if r==0 else 0
            else:
                w=sum((-1)**j*math.comb(K-1,j)*pow(K-1-j,r,MOD) for j in range(K))%MOD
            ans=(ans+dp[N-r]*w)%MOD
    print(ans%MOD)
main()

