from array import array
from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        size = n * m
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))

        # N* is the best length with no turn allowed, beginning at a cell
        # whose expected value is 2 or 0, respectively.
        n2 = [array('H', [0]) * size for _ in range(4)]
        n0 = [array('H', [0]) * size for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    i = r * m + c
                    nr, nc = r + dr, c + dc
                    if grid[r][c] == 2:
                        n2[d][i] = 1
                        if 0 <= nr < n and 0 <= nc < m:
                            n2[d][i] += n0[d][nr * m + nc]
                    elif grid[r][c] == 0:
                        n0[d][i] = 1
                        if 0 <= nr < n and 0 <= nc < m:
                            n0[d][i] += n2[d][nr * m + nc]

        # t* is the best length with at most one clockwise turn remaining.
        t2 = [array('H', [0]) * size for _ in range(4)]
        t0 = [array('H', [0]) * size for _ in range(4)]
        answer = 0
        for d, (dr, dc) in enumerate(dirs):
            clockwise = (d + 1) % 4
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    i = r * m + c
                    nr, nc = r + dr, c + dc
                    if grid[r][c] == 1:
                        answer = max(answer, 1)
                        if 0 <= nr < n and 0 <= nc < m:
                            j = nr * m + nc
                            answer = max(answer, 1 + max(t2[d][j], n2[clockwise][j]))
                    elif grid[r][c] == 2:
                        t2[d][i] = 1
                        if 0 <= nr < n and 0 <= nc < m:
                            j = nr * m + nc
                            t2[d][i] += max(t0[d][j], n0[clockwise][j])
                    elif grid[r][c] == 0:
                        t0[d][i] = 1
                        if 0 <= nr < n and 0 <= nc < m:
                            j = nr * m + nc
                            t0[d][i] += max(t2[d][j], n2[clockwise][j])
        return answer

