from math import factorial
from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        unused = set(range(1, n + 1))
        answer = []
        previous = None

        for pos in range(n):
            chosen = None
            for x in sorted(unused):
                if previous is not None and ((x ^ previous) & 1) == 0:
                    continue

                remaining = n - pos - 1
                odd_left = sum(y & 1 for y in unused if y != x)
                even_left = remaining - odd_left

                if remaining:
                    next_is_odd = ((x & 1) ^ 1) == 1
                    required_odd = ((remaining + 1) // 2
                                    if next_is_odd else remaining // 2)
                    required_even = remaining - required_odd
                else:
                    required_odd = required_even = 0

                if odd_left == required_odd and even_left == required_even:
                    count = factorial(odd_left) * factorial(even_left)
                else:
                    count = 0

                if k > count:
                    k -= count
                else:
                    chosen = x
                    break

            if chosen is None:
                return []
            answer.append(chosen)
            unused.remove(chosen)
            previous = chosen

        return answer

