    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        pw = [1 % k] * n
        for e in range(1, n):
            pw[e] = pw[e-1] * 10 % k
        weights = []
        for i in range(h):
            j = n - 1 - i
            weights.append(pw[i] if i == j else (pw[i] + pw[j]) % k)
        full = (1 << k) - 1
        dp = [0] * (h + 1)
        dp[h] = 1
        for i in range(h - 1, -1, -1):
