            m = 0
            for d in range(10):
                s = d * w % k
                if s == 0:
                    m |= dp[i + 1]
                else:
                    q = dp[i + 1]
                    m |= ((q << s) | (q >> (k - s))) & full
            dp[i] = m
        ans = []
        rem = 0
        for i, w in enumerate(weights):
            for d in range(9, (1 if i == 0 else 0) - 1, -1):
                if (dp[i + 1] >> ((-rem - d * w) % k)) & 1:
                    ans.append(str(d))
                    rem = (rem + d * w) % k
                    break
        left = ''.join(ans)
        return left + left[:n // 2][::-1]

