    for _ in range(n):
        w, v = data[pos], data[pos + 1]
        pos += 2
        nd = [-10**30] * (W + 1)
        for r in range(min(w, W + 1)):
            hull = deque()
            for b in range((W - r) // w + 1):
                old = dp[r + b * w]
                if old > -10**29:
