from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Build the postorder, retaining the required increasing child order.
        order = []
        stack = [(0, 0)]
        while stack:
            x, state = stack.pop()
            if state == 0:
                stack.append((x, 1))
                for y in reversed(children[x]):
                    stack.append((y, 0))
            else:
                order.append(x)

        text = ''.join(s[x] for x in order)
        m = n

        # Manacher radii for odd-length palindromes.
        odd = [0] * m
        left, right = 0, -1
        for i in range(m):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < m and text[i-k] == text[i+k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        # Manacher radii for even-length palindromes; center is between i-1 and i.
        even = [0] * m
        left, right = 0, -1
        for i in range(m):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < m and text[i-k-1] == text[i+k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        position = [0] * n
        size = [1] * n
        for i, x in enumerate(order):
            position[x] = i
        for x in order:
            if parent[x] >= 0:
                size[parent[x]] += size[x]

        answer = []
        for x in range(n):
            r = position[x]
            l = r - size[x] + 1
            length = size[x]
            if length & 1:
                center = (l + r) // 2
                answer.append(odd[center] >= length // 2 + 1)
            else:
                center = (l + r + 1) // 2
                answer.append(even[center] >= length // 2)
        return answer

