class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Prefix sums with equal indices modulo k define subarrays whose
        # lengths are divisible by k. Keep the smallest prefix per residue.
        min_prefix = [None] * k
        min_prefix[0] = 0
        prefix = 0
        answer = None

        for index, value in enumerate(nums, 1):
            prefix += value
            residue = index % k
            previous = min_prefix[residue]
            if previous is not None:
                candidate = prefix - previous
                if answer is None or candidate > answer:
                    answer = candidate
            if previous is None or prefix < previous:
                min_prefix[residue] = prefix

        return answer

