from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 1:
            return 0

        # A line for index i is:
        # dp[i] + (x-i)*nums[i] = nums[i]*x + dp[i]-i*nums[i].
        # Li Chao tree supports inserting these lines and querying x=i.
        tree = [None] * (4 * n)

        def value(line, x):
            return line[0] * x + line[1]

        def add(line, node, left, right):
            current = tree[node]
            if current is None:
                tree[node] = line
                return
            middle = (left + right) // 2
            if value(line, middle) > value(current, middle):
                tree[node], line = line, current
            if left == right:
                return
            if value(line, left) > value(tree[node], left):
                add(line, node * 2, left, middle)
            else:
                add(line, node * 2 + 1, middle + 1, right)

        def query(x, node, left, right):
            line = tree[node]
            result = value(line, x) if line is not None else -10**30
            if left == right:
                return result
            middle = (left + right) // 2
            if x <= middle:
                other = query(x, node * 2, left, middle)
            else:
                other = query(x, node * 2 + 1, middle + 1, right)
            return max(result, other)

        add((nums[0], 0), 1, 0, n - 1)
        answer = 0
        for i in range(1, n):
            answer = query(i, 1, 0, n - 1)
            add((nums[i], answer - i * nums[i]), 1, 0, n - 1)
        return answer

