from typing import List

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        freq = {}
        for value in nums:
            freq[value] = freq.get(value, 0) + 1

        answer = -10**30
        for outlier in nums:
            remainder = total - outlier
            if remainder % 2 == 0:
                sum_value = remainder // 2
                available = freq.get(sum_value, 0)
                if sum_value == outlier:
                    available -= 1
                if available > 0 and outlier > answer:
                    answer = outlier
        return answer

