import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        low = 10 ** (digits - 1)
        high = 10 ** digits - 1

        is_prime = [True] * (high + 1)
        is_prime[0] = is_prime[1] = False
        for p in range(2, int(high ** 0.5) + 1):
            if is_prime[p]:
                start = p * p
                is_prime[start:high + 1:p] = [False] * (((high - start) // p) + 1)

        if is_prime[n] or is_prime[m]:
            return -1

        # The value at the starting node is part of the cost.
        best = {n: n}
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != best.get(value):
                continue
            if value == m:
                return cost

            chars = list(str(value))
            for pos, ch in enumerate(chars):
                digit = ord(ch) - ord('0')
                for new_digit in (digit - 1, digit + 1):
                    if not (0 <= new_digit <= 9):
                        continue
                    # Numbers retain their original number of digits.
                    if pos == 0 and new_digit == 0:
                        continue
                    nxt_chars = chars.copy()
                    nxt_chars[pos] = chr(ord('0') + new_digit)
                    nxt = int(''.join(nxt_chars))
                    if is_prime[nxt]:
                        continue
                    new_cost = cost + nxt
                    if new_cost < best.get(nxt, float('inf')):
                        best[nxt] = new_cost
                        heapq.heappush(heap, (new_cost, nxt))

        return -1

