from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # Z[i] is the length of the common prefix of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        answer = 0
        # prev[j+1] represents LCP(i+1, j+1) while processing i.
        prev = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            curr = [0] * (n + 1)
            first_condition = z[i] >= i
            if first_condition:
                answer += n - i - 1

            for j in range(i + 1, n):
                if nums[i] == nums[j]:
                    curr[j] = 1 + prev[j + 1]
                    if not first_condition and curr[j] >= j - i:
                        answer += 1
            prev = curr

        return answer

