class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        n = len(s)
        base = s.count('1')
        best = base
        i = 0
        while i < n:
            if s[i] == '0':
                i += 1
                continue
            j = i
            while j < n and s[j] == '1':
                j += 1
            if i > 0 and j < n:
                l = i - 1
                while l >= 0 and s[l] == '0':
                    l -= 1
                r = j
                while r < n and s[r] == '0':
                    r += 1
                gain = (i - l - 1) + (r - j)
                if base + gain > best:
                    best = base + gain
            i = j
        return best

