from typing import List

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        lo = -10**30
        hi = 10**30
        for value, (lower, upper) in zip(original, bounds):
            lo = max(lo, lower - value)
            hi = min(hi, upper - value)
        return max(0, hi - lo + 1)
